SELECT COUNT(*) INTO n FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE IN(CONVERT(X'6e70635f7479706573' USING utf8mb4),CONVERT(X'737061776e67726f7570' USING utf8mb4),CONVERT(X'737061776e656e747279' USING utf8mb4),CONVERT(X'737061776e32' USING utf8mb4),CONVERT(X'7a6f6e655f73746174655f737061776e73' USING utf8mb4),CONVERT(X'696e76656e746f7279' USING utf8mb4),CONVERT(X'6368617261637465725f63757272656e6379' USING utf8mb4),CONVERT(X'6e696768746361705f6d61726b65745f7374617465' USING utf8mb4),CONVERT(X'6e696768746361705f6d61726b65745f636174616c6f67' USING utf8mb4),CONVERT(X'6e696768746361705f6d61726b65745f6163746f7273' USING utf8mb4),CONVERT(X'6e696768746361705f6d61726b65745f6f6666657273' USING utf8mb4),CONVERT(X'6e696768746361705f6d61726b65745f747261646573' USING utf8mb4));
