SELECT COUNT(*) INTO n FROM nightcap_market_actors;
IF n<>22 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Actor set changed'; END IF;
SELECT COUNT(*) INTO n FROM npc_types WHERE id=999500 AND name=CONVERT(X'52656c6c616e5f526964676577616c6b6572' USING utf8mb4);
IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Trader identity changed'; END IF;
SELECT COUNT(*) INTO n FROM spawngroup WHERE id=999500 AND name='NightcapMarket999500';
IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Trader group changed'; END IF;
SELECT COUNT(*) INTO n FROM spawn2 WHERE id=999500 AND spawngroupID=999500 AND zone='ecommons' AND version=0;
