IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Trader spawn changed'; END IF;
SELECT COUNT(*) INTO n FROM spawnentry WHERE spawngroupID BETWEEN 999500 AND 999509 OR npcID BETWEEN 999500 AND 999509;
IF n<>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unexpected spawn reference'; END IF;
SELECT COUNT(*) INTO n FROM spawn2 WHERE spawngroupID BETWEEN 999500 AND 999509;
IF n<>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unexpected spawn placement'; END IF;
UPDATE nightcap_market_state SET enabled=0 WHERE id=1;
DELETE FROM nightcap_market_offers;
DELETE FROM nightcap_market_actors;
DELETE FROM zone_state_spawns WHERE zone_id=22 AND instance_id=0 AND is_corpse=0 AND is_zone=0 AND (npc_id BETWEEN 999500 AND 999509 OR spawngroup_id BETWEEN 999500 AND 999509 OR spawn2_id BETWEEN 999500 AND 999509);
